	if got := Total(1, 2); got != 3 {
		t.Errorf("Total(1, 2) = %d, want 3", got)
	}
}

func TestDiscount(t *testing.T) {
	if testing.Short() {
		t.Skip("slow")
	}
	if got := Discount(99); got != 0 {
		t.Errorf("Discount(99) = %d, want 0", got)
	}
}
